CREATE TABLE [dbo].[ivroptions](	  [IVR_id] INT NOT NULL	, [selectedOption] VARCHAR(5) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [date] DATETIME NOT NULL	, [saveType] TINYINT NULL	, [name] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL DEFAULT('')	, [questionId] INT NULL	, [surveyId] INT NULL	, [cal_id] INT NULL	, [callType] TINYINT NULL)CREATE NONCLUSTERED INDEX [IX_ivroptions] ON [dbo].[ivroptions] ([date] ASC)